-- База знаний: справочник подкормок, сорта популярных видов и новые виды.
--
-- 1. public.fertilizers — программы подкормки (как soil_mixes для грунтов): ориентир N:P:K,
--    форма, доза, признаки недокорма и перекорма, советы. Каждому виду назначена одна программа
--    (care_profiles.fertilizer_slug); как часто и в какие месяцы — по-прежнему в care_profiles.
-- 2. species.cultivars — популярные сорта (название, русская транскрипция, чем отличается).
--    Поиск находит вид и по названию сорта («Тай Констелейшн» → монстера деликатесная).
-- 3. Новые виды — в первую очередь те, что садоводы уже добавили в коллекции, но не нашли в базе:
--    антуриум Шерцера, алоказия длиннолопастная, клейстокактус Винтера, росянка, маммиллярия Гана…
-- Латинские названия — по POWO, прежние — в synonyms. Токсичность для животных — по ASPCA.
-- Миграция идемпотентна.

create table if not exists public.fertilizers (
  slug    text primary key,
  name    jsonb not null,
  summary jsonb not null,
  npk     smallint[] check (npk is null or cardinality(npk) = 3),
  form    jsonb not null,
  dose    jsonb not null,
  signs_under jsonb not null default '{}',
  signs_over  jsonb not null default '{}',
  tips    jsonb not null default '{}',
  sort    smallint not null
);

alter table public.fertilizers enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies
                  where schemaname = 'public' and tablename = 'fertilizers' and policyname = 'kb_read') then
    create policy kb_read on public.fertilizers for select to anon, authenticated using (true);
  end if;
end $$;
revoke insert, update, delete on public.fertilizers from anon, authenticated;

alter table public.care_profiles
  add column if not exists fertilizer_slug text references public.fertilizers(slug);
create index if not exists care_profiles_fertilizer_slug_idx on public.care_profiles (fertilizer_slug);

alter table public.species add column if not exists cultivars jsonb not null default '[]'
  check (jsonb_typeof(cultivars) = 'array');

-- Поиск по названиям — теперь и по сортам.
create or replace function public.species_search_refresh()
returns trigger
language plpgsql
set search_path = public, extensions
as $$
declare
  names text;
  sorts text;
begin
  select coalesce(string_agg(value, ' '), '')
    into names
    from jsonb_each(new.common_names) as lang(key, arr),
         jsonb_array_elements_text(arr) as value;
  select coalesce(string_agg(concat_ws(' ', c ->> 'name', c ->> 'ru'), ' '), '')
    into sorts
    from jsonb_array_elements(coalesce(new.cultivars, '[]')) as c;
  new.search_text := lower(new.latin_name || ' ' || names || ' '
                           || array_to_string(new.synonyms, ' ') || ' ' || sorts);
  new.search_tsv := to_tsvector('simple', new.search_text);
  new.updated_at := now();
  if tg_op = 'UPDATE' then
    new.kb_version := old.kb_version + 1;
  end if;
  return new;
end;
$$;

insert into public.fertilizers (slug, name, summary, npk, form, dose, signs_under, signs_over, tips, sort) values
  ('foliage', '{"ru": "Для декоративно-лиственных"}'::jsonb, '{"ru": "Азот чуть преобладает: он отвечает за рост и насыщенный цвет листьев. Подходит монстерам, филодендронам, калатеям, драценам и большинству зелёных растений."}'::jsonb, '{"3","1","2"}'::smallint[], '{"ru": "Жидкое комплексное удобрение с микроэлементами — в воду для полива."}'::jsonb, '{"ru": "Половина дозы с упаковки: в горшке соли копятся быстрее, чем в саду."}'::jsonb,
