  ('flowering', '{"ru": "Для цветущих"}'::jsonb, '{"ru": "Больше фосфора и калия: они закладывают бутоны и дают долгое цветение. Азота меньше — иначе листья растут в ущерб цветкам."}'::jsonb, '{"1","2","2"}'::smallint[], '{"ru": "Жидкое удобрение «для цветущих» с микроэлементами."}'::jsonb, '{"ru": "Половина дозы с упаковки; до бутонизации можно чередовать с удобрением для лиственных."}'::jsonb,
   '{"ru": ["Мало бутонов или они осыпаются", "Короткое цветение, мелкие цветки", "Листья бледные, растение вытягивается"]}'::jsonb, '{"ru": ["Много листвы и нет цветков (перебор азота)", "Бурые края листьев, налёт на грунте", "Бутоны сохнут, не раскрывшись"]}'::jsonb, '{"ru": ["Начинайте подкормки, когда растение трогается в рост весной; в период покоя не кормите.", "Во время цветения кормите стабильно, без резких перерывов.", "Отцветшие цветоносы удаляйте — силы уйдут в новые бутоны."]}'::jsonb, 20),
  ('universal', '{"ru": "Универсальное сбалансированное"}'::jsonb, '{"ru": "Азот, фосфор и калий поровну — для деревьев и кустарников в кадках, фикусов, шеффлер, бонсай."}'::jsonb, '{"1","1","1"}'::smallint[], '{"ru": "Жидкое или гранулы длительного действия (одна заправка на 2–3 месяца)."}'::jsonb, '{"ru": "Жидкое — половина дозы; гранулы — по инструкции для комнатных, не больше."}'::jsonb,
   '{"ru": ["Нижние листья желтеют и опадают", "Годовой прирост меньше обычного", "Листья светлее, чем были"]}'::jsonb, '{"ru": ["Солевая корка на грунте", "Опадание листьев при влажном грунте", "Бурые пятна по краям листьев"]}'::jsonb, '{"ru": ["Гранулы длительного действия удобны для крупных кадок: их меньше шанс передозировать.", "Весной, когда растение трогается в рост, начните с половины обычной дозы.", "Бонсай кормят часто, но очень слабо — четверть дозы."]}'::jsonb, 30),
  ('cactus', '{"ru": "Для кактусов и суккулентов"}'::jsonb, '{"ru": "Мало азота, больше фосфора и калия: растение остаётся плотным, не вытягивается и лучше цветёт. Кормят редко."}'::jsonb, '{"1","2","3"}'::smallint[], '{"ru": "Жидкое удобрение «для кактусов и суккулентов»."}'::jsonb, '{"ru": "Половина дозы, не чаще раза в месяц и только в период роста."}'::jsonb,
