  ('minimal', '{"ru": "Почти без подкормок"}'::jsonb, '{"ru": "«Живые камни» и похожие суккуленты растут в бедной почве: удобрения им скорее вредят."}'::jsonb, '{"1","2","3"}'::smallint[], '{"ru": "Кактусовое удобрение, очень слабо."}'::jsonb, '{"ru": "Четверть дозы, 1–2 раза за лето — или вовсе без подкормок."}'::jsonb,
