  ('orchid', '{"ru": "Для орхидей"}'::jsonb, '{"ru": "Слабое сбалансированное удобрение для эпифитов: их корни очень чувствительны к солям."}'::jsonb, '{"1","1","1"}'::smallint[], '{"ru": "Жидкое удобрение «для орхидей»; для листовой подкормки — спрей для орхидей."}'::jsonb, '{"ru": "Четверть–половина дозы, примерно каждый 2–3-й полив; раз в месяц — полив чистой водой."}'::jsonb,
   '{"ru": ["Листья мягкие и светлые, новые — мельче", "Нет цветоносов больше года при хорошем свете"]}'::jsonb, '{"ru": ["Кончики корней буреют и сохнут", "Белый налёт на коре и горшке", "Бутоны опадают"]}'::jsonb, '{"ru": ["Сухие корни не кормите — сначала намочите кору чистой водой.", "Во время цветения и в покое подкормки сокращают вдвое или прекращают.", "После пересадки ждите месяц: повреждённые корни легко обжечь."]}'::jsonb, 60),
  ('acid', '{"ru": "Для кислолюбивых"}'::jsonb, '{"ru": "Азалиям, гардениям, камелиям и гортензиям нужен кислый грунт и железо в доступной форме, иначе листья желтеют с зелёными жилками (хлороз)."}'::jsonb, '{"1","1","1"}'::smallint[], '{"ru": "Удобрение «для азалий / рододендронов» с хелатом железа, без кальция и хлора."}'::jsonb, '{"ru": "Половина дозы; при хлорозе — дополнительно хелат железа по инструкции."}'::jsonb,
   '{"ru": ["Молодые листья жёлтые с зелёными жилками (не хватает железа)", "Бутоны мелкие, осыпаются"]}'::jsonb, '{"ru": ["Бурые края листьев", "Опадание бутонов"]}'::jsonb, '{"ru": ["Поливайте мягкой отстоянной или фильтрованной водой: жёсткая вода защелачивает грунт.", "Раз в месяц можно подкислять воду: пара кристаллов лимонной кислоты на литр.", "Золу, известь и «универсальные» подкормки с кальцием не давайте."]}'::jsonb, 70),
