   '{"ru": ["Мелкие бледные листья", "Томаты: мало завязей, плоды мелкие"]}'::jsonb, '{"ru": ["Травы теряют аромат (перебор азота)", "Томаты: пышная ботва и мало плодов"]}'::jsonb, '{"ru": ["Для зелени на еду выбирайте органические удобрения.", "Томатам с началом цветения нужен калий — удобрение «для томатов».", "Первые 3–4 недели после посева не кормите — хватает запаса в грунте."]}'::jsonb, 130)
on conflict (slug) do update set
  name = excluded.name, summary = excluded.summary, npk = excluded.npk, form = excluded.form, dose = excluded.dose,
  signs_under = excluded.signs_under, signs_over = excluded.signs_over, tips = excluded.tips, sort = excluded.sort;

